import {randomUUID} from 'node:crypto';
import {context, trace} from '@opentelemetry/api';
import {
  createUIMessageStream,
  isStepCount,
  streamText,
  toUIMessageStream,
  type GenerateTextEndEvent,
  type InferUIMessageChunk,
  type LanguageModel,
  type LanguageModelUsage,
  type ModelMessage,
  type ToolSet,
} from 'ai';
import type {Project} from '../sandbox/project';
import {commitTurn} from './checkpoint';
import {AGENT_CONFIG} from './config';
import {errorStatus, REFUSED, sandboxMessage, STEP_LIMIT, UNVERIFIED, userMessage, VERIFY_FAILED} from './errors';
import {logEvent} from './events';
import {checkPolicy} from './policy';
import {REPAIR_PROMPT, SYSTEM_PROMPT} from './system-prompt';
import {createTools, proposedDiff, TOOL_DEFINITIONS} from './tools';
import {hashOf, TRACER_NAME} from './trace';
import type {AgentMessage, DeniedCall, ToolName, TurnRecord, Usage, VerifyResult} from './types';
import {verifyProject} from './verify';

export type AgentChunk = InferUIMessageChunk<AgentMessage>;

export const SYSTEM_PROMPT_HASH = hashOf({system: SYSTEM_PROMPT, repair: REPAIR_PROMPT});
export const TOOL_CONFIG_HASH = hashOf({config: AGENT_CONFIG, tools: TOOL_DEFINITIONS});

type Outcome = {type: 'end'; event: GenerateTextEndEvent<ToolSet>} | {type: 'stopped'} | {type: 'error'; error: unknown};

const addUsage = (total: Usage, u: LanguageModelUsage) => {
  total.inputTokens += u.inputTokens ?? 0;
  total.outputTokens += u.outputTokens ?? 0;
  total.cachedInputTokens += u.inputTokenDetails.cacheReadTokens ?? 0;
};

export function noticeFor(record: TurnRecord): string | undefined {
  if (record.status === 'error') return record.error;
  if (record.status === 'failed') return VERIFY_FAILED;
  if (record.status === 'unverified') return UNVERIFIED;
  if (record.stepLimitReached && record.status !== 'stopped') return STEP_LIMIT;
  return undefined;
}

const lastUserText = (messages: ModelMessage[]) => {
  const content = messages.findLast(m => m.role === 'user')?.content;
  return typeof content === 'string' ? content : (content ?? []).map(p => (p.type === 'text' ? p.text : '')).join('');
};

// A skipped check is never a pass: the turn is only 'passed' when every check ran and passed.
const checkedStatus = (verify: VerifyResult) => (verify.checks.every(c => c.status === 'passed') ? 'passed' : 'unverified');

export const repairMessage = (verify: VerifyResult) =>
  REPAIR_PROMPT.replace(
    '{errors}',
    verify.checks
      .filter(c => c.status === 'failed')
      .map(c => `${c.name}:\n${c.errors.join('\n')}`)
      .join('\n\n'),
  );

async function approvalDiff(project: Project, tool: string, input: {path: string; oldString?: string; newString?: string; content?: string}, path: string) {
  if (tool !== 'write_file') return proposedDiff(path, input.oldString ?? '', input.newString ?? '');
  const before = await project.read(`${project.root}/${path}`).catch(() => null);
  return proposedDiff(path, before, input.content ?? '');
}

function approvalEvents(messages: ModelMessage[], turnId: string, traceId: string) {
  const last = messages.at(-1);
  if (last?.role !== 'tool') return;
  const requests = new Map<string, string>();
  for (const m of messages) {
    if (m.role !== 'assistant' || typeof m.content === 'string') continue;
    for (const p of m.content) if (p.type === 'tool-approval-request') requests.set(p.approvalId, p.toolCallId);
  }
  for (const p of last.content) {
    if (p.type !== 'tool-approval-response') continue;
    const toolCallId = requests.get(p.approvalId) ?? p.approvalId;
    logEvent({type: p.approved ? 'approve' : 'deny', turnId, traceId, toolCallId, at: new Date().toISOString()});
  }
}

export function runAgent({
  model,
  messages,
  project,
  abortSignal,
  keepSandbox = false,
}: {
  model: Exclude<LanguageModel, string>;
  messages: ModelMessage[];
  project?: Project;
  abortSignal?: AbortSignal;
  keepSandbox?: boolean;
}) {
  const span = trace.getTracer(TRACER_NAME).startSpan('betterlook.turn');
  const spanContext = trace.setSpan(context.active(), span);
  const record: TurnRecord = {
    id: randomUUID(),
    traceId: span.spanContext().traceId,
    sandboxId: project?.id ?? '',
    prompt: lastUserText(messages),
    provider: model.provider,
    model: model.modelId,
    systemPromptHash: SYSTEM_PROMPT_HASH,
    toolConfigHash: TOOL_CONFIG_HASH,
    toolCalls: [],
    usage: {inputTokens: 0, outputTokens: 0, cachedInputTokens: 0, costUsd: null},
    diff: '',
    filesTouched: [],
    verify: null,
    repairAttempted: false,
    repairVerify: null,
    stepLimitReached: false,
    status: 'running',
    checkpoint: null,
    sandbox: null,
    startedAt: new Date().toISOString(),
    endedAt: null,
  };
  span.setAttributes({
    'langfuse.trace.name': 'betterlook.turn',
    'langfuse.trace.input': record.prompt,
    'langfuse.trace.metadata.turnId': record.id,
    'langfuse.trace.metadata.systemPromptHash': record.systemPromptHash,
    'langfuse.trace.metadata.toolConfigHash': record.toolConfigHash,
  });

  let resolveTurn: (turn: TurnRecord) => void;
  const turn = new Promise<TurnRecord>(resolve => (resolveTurn = resolve));
  const end = (patch: Partial<TurnRecord>) => void Object.assign(record, patch, {endedAt: new Date().toISOString()});
  const finalize = () => {
    span.setAttributes({
      'langfuse.trace.output': JSON.stringify(record),
      'langfuse.trace.metadata.status': record.status,
      'langfuse.trace.metadata.checkpointId': record.checkpoint?.id ?? '',
    });
    span.end();
    resolveTurn(record);
  };

  const stream = createUIMessageStream<AgentMessage>({
    execute: async ({writer}) => {
      const callModel = (callMessages: ModelMessage[]) => {
        let settle: (outcome: Outcome) => void;
        const outcome = new Promise<Outcome>(resolve => (settle = resolve));
        const result = context.with(spanContext, () =>
          streamText({
            model,
            instructions: SYSTEM_PROMPT || undefined,
            messages: callMessages,
            stopWhen: isStepCount(AGENT_CONFIG.maxSteps),
            maxOutputTokens: AGENT_CONFIG.maxOutputTokens,
            // Claude Sonnet 5.5 400s on non-default sampling, forced toolChoice and disabled thinking, so none are set.
            providerOptions: {
              openai: {store: false, ...(AGENT_CONFIG.promptCachePerProject && project ? {promptCacheKey: project.id} : {})},
              anthropic: {fallbacks: 'default'},
            },
            tools: project ? createTools(project, record.toolCalls) : undefined,
            toolApproval: async ({toolCall}) => {
              if (!project) return undefined;
              const decision = checkPolicy(toolCall.toolName, toolCall.input, project.root);
              if (decision.type === 'deny') {
                const denied: DeniedCall = {
                  toolCallId: toolCall.toolCallId,
                  tool: toolCall.toolName,
                  args: toolCall.input,
                  reason: decision.reason,
                  message: decision.message,
                  at: new Date().toISOString(),
                };
                console.warn('[policy] denied:', denied.tool, denied.reason);
                record.toolCalls.push({id: denied.toolCallId, tool: denied.tool, args: denied.args, result: denied.message, decision: 'denied', denied, startedAt: denied.at, durationMs: 0});
                writer.write({type: 'data-denied', id: denied.toolCallId, data: denied});
                return {type: 'denied', reason: decision.message};
              }
              if (decision.type === 'approve') {
                const diff = await approvalDiff(project, toolCall.toolName, toolCall.input as {path: string}, decision.path);
                writer.write({type: 'data-approval', id: toolCall.toolCallId, data: {toolCallId: toolCall.toolCallId, tool: toolCall.toolName as ToolName, path: decision.path, diff}});
                return 'user-approval';
              }
              return undefined;
            },
            abortSignal,
            onEnd: event => settle({type: 'end', event}),
            onAbort: () => settle({type: 'stopped'}),
            onError: ({error}) => {
              console.error('[agent] model call failed:', errorStatus(error));
              settle({type: 'error', error});
            },
          }),
        );
        return {result, outcome};
      };

      const settled = (outcome: Outcome) => {
        if (outcome.type === 'end') {
          addUsage(record.usage, outcome.event.totalUsage);
          if (outcome.event.finishReason === 'content-filter') {
            end({status: 'error', error: REFUSED});
            return false;
          }
          if (outcome.event.steps.length >= AGENT_CONFIG.maxSteps && outcome.event.finishReason === 'tool-calls') record.stepLimitReached = true;
          return true;
        }
        end(outcome.type === 'stopped' ? {status: 'stopped'} : {status: 'error', error: userMessage(outcome.error)});
        return false;
      };

      const pipe = async (chunks: ReadableStream<AgentChunk>) => {
        for await (const chunk of chunks) writer.write(chunk);
      };

      try {
        approvalEvents(messages, record.id, record.traceId);
        const first = callModel(messages);
        await pipe(
          toUIMessageStream<ToolSet, AgentMessage>({
            stream: first.result.stream,
            sendFinish: false,
            onError: userMessage,
            messageMetadata: ({part}) => (part.type === 'start' ? {turnId: record.id, traceId: record.traceId} : undefined),
          }),
        );
        const outcome = await first.outcome;
        if (!settled(outcome) || outcome.type !== 'end') return;
        if (outcome.event.content.some(p => p.type === 'tool-approval-request' && !p.isAutomatic)) return end({status: 'awaiting-approval'});
        if (!project) return end({status: 'passed'});

        const saved = await commitTurn(project, record.id);
        writer.write({type: 'data-checkpoint', id: 'checkpoint', data: saved.checkpoint});
        writer.write({type: 'data-diff', id: 'diff', data: saved.diff});
        const verify = await verifyProject(project);
        writer.write({type: 'data-verify', id: 'verify', data: verify});
        if (verify.ok) return end({status: checkedStatus(verify), verify, checkpoint: saved.checkpoint, ...saved.diff});

        const repair = callModel([...messages, ...(await first.result.response).messages, {role: 'user', content: repairMessage(verify)}]);
        await pipe(toUIMessageStream<ToolSet, AgentMessage>({stream: repair.result.stream, sendStart: false, sendFinish: false, onError: userMessage}));
        const repairOutcome = await repair.outcome;
        if (!settled(repairOutcome)) return;
        const repaired = await commitTurn(project, record.id, saved.checkpoint.parentId);
        writer.write({type: 'data-checkpoint', id: 'checkpoint', data: repaired.checkpoint});
        writer.write({type: 'data-diff', id: 'diff', data: repaired.diff});
        const repairVerify = await verifyProject(project);
        writer.write({type: 'data-verify', id: 'repair-verify', data: repairVerify});
        end({
          status: repairVerify.ok ? checkedStatus(repairVerify) : 'failed',
          verify,
          repairAttempted: true,
          repairVerify,
          checkpoint: repaired.checkpoint,
          ...repaired.diff,
        });
      } catch (error) {
        console.error('[agent] turn failed:', error instanceof Error ? error.message : 'unknown');
        const message = sandboxMessage(error);
        if (!record.endedAt) end({status: 'error', error: message});
        writer.write({type: 'error', errorText: message});
      } finally {
        writer.write({type: 'finish', messageMetadata: {status: record.status, notice: noticeFor(record)}});
        // Stopped as soon as the turn ends, so the Hobby CPU quota is not spent idling until the timeout.
        if (project?.stop && !keepSandbox) record.sandbox = await project.stop().catch(() => null);
        finalize();
      }
    },
    onError: userMessage,
  });

  return {stream, turn};
}
import type {ToolName} from './types';

export const AGENT_CONFIG = {
  maxSteps: 20,
  maxOutputTokens: 8_000,
  tools: ['list_files', 'read_file', 'search', 'edit_file', 'write_file', 'typecheck'] satisfies ToolName[],
  deniedPaths: ['.git', 'node_modules'],
  approvalFiles: ['package.json', 'package-lock.json', '*.lock', 'pnpm-lock.yaml', 'tsconfig*.json', '*.config.*', '.env*'],
  maxToolOutputChars: 20_000,
  promptCachePerProject: true,
} as const;

export const RUNNER_CONFIG = {
  concurrency: 3,
  maxAttempts: 3,
  backoffMs: 5_000,
} as const;

export const SANDBOX_CONFIG = {
  vcpus: 2,
  timeoutMs: 10 * 60_000,
  snapshotExpirationMs: 7 * 24 * 60 * 60_000,
} as const;
import type {UIMessage} from 'ai';

export type ProviderId = 'openai' | 'anthropic';

export type ProviderCredential =
  | {provider: ProviderId; kind: 'api-key'; apiKey: string}
  | {provider: ProviderId; kind: 'oauth'; accessToken: string; expiresAt?: number};

export type ToolName = 'list_files' | 'read_file' | 'search' | 'edit_file' | 'write_file' | 'typecheck';

export interface DeniedCall {
  toolCallId: string;
  tool: string;
  args: unknown;
  reason: 'outside-project' | 'not-allowlisted' | 'user-denied';
  message: string;
  at: string;
}

export interface ToolCallRecord {
  id: string;
  tool: string;
  args: unknown;
  result: unknown;
  decision: 'allowed' | 'denied' | 'approved';
  denied?: DeniedCall;
  startedAt: string;
  durationMs: number;
}

export type VerifyCheckStatus = 'passed' | 'failed' | 'skipped';

export interface VerifyCheck {
  name: 'typecheck' | 'build' | 'runtime';
  status: VerifyCheckStatus;
  errors: string[];
  durationMs: number;
}

export interface VerifyResult {
  ok: boolean;
  checks: VerifyCheck[];
}

export interface Checkpoint {
  id: string;
  parentId: string;
  sandboxId: string;
  turnId: string;
  createdAt: string;
}

export interface Usage {
  inputTokens: number;
  outputTokens: number;
  cachedInputTokens: number;
  costUsd: number | null;
}

export interface SandboxUsage {
  vcpus: number;
  activeCpuMs: number | null;
  durationMs: number | null;
}

export type TurnStatus = 'running' | 'awaiting-approval' | 'passed' | 'unverified' | 'failed' | 'stopped' | 'error';

export interface TurnRecord {
  id: string;
  traceId: string;
  sandboxId: string;
  prompt: string;
  provider: string;
  model: string;
  systemPromptHash: string;
  toolConfigHash: string;
  toolCalls: ToolCallRecord[];
  usage: Usage;
  diff: string;
  filesTouched: string[];
  verify: VerifyResult | null;
  repairAttempted: boolean;
  repairVerify: VerifyResult | null;
  stepLimitReached: boolean;
  status: TurnStatus;
  error?: string;
  checkpoint: Checkpoint | null;
  sandbox: SandboxUsage | null;
  startedAt: string;
  endedAt: string | null;
}

export type TurnEvent =
  | {type: 'restore'; turnId: string; traceId?: string; checkpointId: string; at: string}
  | {type: 'keep'; turnId: string; traceId?: string; at: string}
  | {type: 'approve'; turnId: string; traceId?: string; toolCallId: string; at: string}
  | {type: 'deny'; turnId: string; traceId?: string; toolCallId: string; at: string};

export interface PendingApproval {
  toolCallId: string;
  tool: ToolName;
  path: string;
  diff: string;
}

export interface TurnDiff {
  diff: string;
  filesTouched: string[];
}

export type AgentDataParts = {
  denied: DeniedCall;
  approval: PendingApproval;
  verify: VerifyResult;
  checkpoint: Checkpoint;
  diff: TurnDiff;
};

export interface AgentMetadata {
  model?: string;
  turnId?: string;
  traceId?: string;
  status?: TurnStatus;
  notice?: string;
}

export type AgentMessage = UIMessage<AgentMetadata, AgentDataParts>;
import type {Project} from '../sandbox/project';
import type {Checkpoint, TurnDiff} from './types';

const COMMIT = /^[0-9a-f]{7,40}$/;

async function git(project: Project, args: string[]) {
  const {exitCode, output} = await project.run('git', args);
  if (exitCode !== 0) throw new Error(`git ${args[0]} failed (exit ${exitCode})`);
  return output.trim();
}

const head = (project: Project) => git(project, ['rev-parse', 'HEAD']);

export async function commitTurn(project: Project, turnId: string, base?: string): Promise<{checkpoint: Checkpoint; diff: TurnDiff}> {
  await git(project, ['add', '-A']);
  const parentId = await head(project);
  const from = base ?? parentId;
  const diff = await git(project, ['diff', '--cached', from]);
  const filesTouched = (await git(project, ['diff', '--cached', '--name-only', from])).split('\n').filter(Boolean);
  await git(project, ['commit', '-q', '--allow-empty', '-m', `turn ${turnId}`]);
  return {
    checkpoint: {id: await head(project), parentId: from, sandboxId: project.id, turnId, createdAt: new Date().toISOString()},
    diff: {diff, filesTouched},
  };
}

export async function restoreCheckpoint(project: Project, checkpointId: string): Promise<string> {
  if (!COMMIT.test(checkpointId)) throw new Error('Not a checkpoint id.');
  await git(project, ['read-tree', '-u', '--reset', checkpointId]);
  await git(project, ['commit', '-q', '--allow-empty', '-m', `restore ${checkpointId}`]);
  return head(project);
}
import type {Project} from '../sandbox/project';
import {CHECKER_SCRIPT} from '../sandbox/runtime-check';
import {PREVIEW_PORT} from '../sandbox/starter';
import type {VerifyCheck, VerifyResult} from './types';

const MAX_ERROR_LINES = 40;
const tail = (output: string) => output.trim().split('\n').slice(-MAX_ERROR_LINES).join('\n');

async function timed(name: VerifyCheck['name'], fn: () => Promise<Omit<VerifyCheck, 'name' | 'durationMs'>>): Promise<VerifyCheck> {
  const start = Date.now();
  return {name, ...(await fn()), durationMs: Date.now() - start};
}

const script = (project: Project, name: 'typecheck' | 'build') =>
  timed(name, async () => {
    const {exitCode, output} = await project.run('npm', ['run', '--silent', name]);
    return exitCode === 0 ? {status: 'passed', errors: []} : {status: 'failed', errors: [tail(output)]};
  });

export function runtimeErrors(exitCode: number, output: string): Omit<VerifyCheck, 'name' | 'durationMs'> {
  const json = output.trim().split('\n').at(-1) ?? '';
  if (exitCode !== 0 || !json.startsWith('[')) return {status: 'skipped', errors: [`The runtime check could not run: ${tail(output)}`]};
  const errors: string[] = JSON.parse(json);
  return errors.length ? {status: 'failed', errors} : {status: 'passed', errors: []};
}

export async function verifyProject(project: Project): Promise<VerifyResult> {
  const typecheck = await script(project, 'typecheck');
  const build = await script(project, 'build');
  const runtime =
    build.status === 'failed'
      ? {name: 'runtime' as const, status: 'skipped' as const, errors: [], durationMs: 0}
      : await timed('runtime', async () => {
          const {exitCode, output} = await project.run('node', [CHECKER_SCRIPT, `http://localhost:${PREVIEW_PORT}`]);
          return runtimeErrors(exitCode, output);
        });
  const checks = [typecheck, build, runtime];
  return {ok: checks.every(c => c.status !== 'failed'), checks};
}
import {createAnthropic} from '@ai-sdk/anthropic';
import {createOpenAI} from '@ai-sdk/openai';
import {providerOf} from './models';
import type {ProviderCredential} from './types';

export function languageModel(modelId: string, credential: ProviderCredential) {
  if (providerOf(modelId) !== credential.provider) {
    throw new Error(`Model ${modelId} is not available for provider ${credential.provider}.`);
  }
  if (credential.provider === 'anthropic') {
    if (credential.kind !== 'api-key') throw new Error('Anthropic accepts API keys only.');
    return createAnthropic({apiKey: credential.apiKey})(modelId);
  }
  const token = credential.kind === 'api-key' ? credential.apiKey : credential.accessToken;
  return createOpenAI({apiKey: token})(modelId);
}

// Body credentials are API keys only; an OAuth token must come from the server-side session cookie.
export function parseCredential(value: unknown): ProviderCredential | null {
  if (typeof value !== 'object' || value === null) return null;
  const c = value as Record<string, unknown>;
  if ((c.provider !== 'openai' && c.provider !== 'anthropic') || c.kind !== 'api-key' || typeof c.apiKey !== 'string' || !c.apiKey) return null;
  return {provider: c.provider, kind: c.kind, apiKey: c.apiKey};
}
import {randomBytes} from 'node:crypto';
import {context, trace, TraceFlags} from '@opentelemetry/api';
import {TRACER_NAME} from './trace';
import type {TurnEvent} from './types';

export function logEvent(event: TurnEvent) {
  console.info('[event]', JSON.stringify(event));
  const parent = event.traceId
    ? trace.setSpanContext(context.active(), {traceId: event.traceId, spanId: randomBytes(8).toString('hex'), traceFlags: TraceFlags.SAMPLED, isRemote: true})
    : context.active();
  const span = trace.getTracer(TRACER_NAME).startSpan(`betterlook.event.${event.type}`, {}, parent);
  span.setAttributes({
    'langfuse.observation.type': 'event',
    'langfuse.observation.metadata.event': JSON.stringify(event),
    'langfuse.trace.metadata.lastEvent': event.type,
  });
  span.end();
}

export function parseKeepEvent(value: unknown): TurnEvent | null {
  const e = value as Record<string, unknown> | null;
  if (e?.type !== 'keep' || typeof e.turnId !== 'string') return null;
  return {type: 'keep', turnId: e.turnId, traceId: typeof e.traceId === 'string' ? e.traceId : undefined, at: new Date().toISOString()};
}
import {APICallError} from 'ai';
import type {ProviderId} from './types';

export const KEY_REJECTED = 'Your API key or sign-in was rejected. Check it and try again.';
export const RATE_LIMITED = 'The model provider is rate limiting requests. Wait a minute and try again.';
export const PROVIDER_FAILED = 'The model provider returned an error. Try again.';
export const VERIFY_FAILED = 'The change still fails its checks after one repair attempt. Restore the previous version or describe what to fix.';
export const UNVERIFIED = 'The change builds, but the visual check could not run, so it is not verified. Check the preview yourself.';
export const STEP_LIMIT = 'The agent hit its step limit before finishing. Send another message to let it continue.';
export const REFUSED = 'The model declined this request. Rephrase it or pick another model.';
export const SANDBOX_FAILED = 'The preview sandbox stopped responding. Reload to try again.';
export const SANDBOX_QUOTA = 'The preview sandbox has used its free monthly quota, so new sandboxes are paused until it resets.';

const PROVIDER_NAMES: Record<ProviderId, string> = {openai: 'OpenAI', anthropic: 'Anthropic'};

export const missingKey = ({provider, label}: {provider: ProviderId; label: string}) =>
  `${provider === 'openai' ? 'Sign in or add' : 'Add'} an ${PROVIDER_NAMES[provider]} API key to use ${label}.`;

// The SDK wraps errors it retried; the provider's status is on the last attempt.
const apiError = (error: unknown) => {
  const last = (error as {lastError?: unknown} | null)?.lastError ?? error;
  return APICallError.isInstance(last) ? last : null;
};

// Never forward provider text: OpenAI's 401 body echoes part of the key. Anthropic 529 overloaded and 5xx fall through to PROVIDER_FAILED.
export function userMessage(error: unknown): string {
  const status = apiError(error)?.statusCode;
  if (status === 401 || status === 403) return KEY_REJECTED;
  if (status === 429) return RATE_LIMITED;
  return PROVIDER_FAILED;
}

export function errorStatus(error: unknown): number | string {
  const api = apiError(error);
  return api ? (api.statusCode ?? 'no-status') : error instanceof Error ? error.name : 'unknown';
}

// Vercel Sandbox answers 402 payment_required once the Hobby quota is used up and creation pauses.
export const sandboxQuotaExceeded = (error: unknown) => (error as {response?: {status?: number}} | null)?.response?.status === 402;

export const sandboxMessage = (error: unknown) => (sandboxQuotaExceeded(error) ? SANDBOX_QUOTA : SANDBOX_FAILED);

