export type AgentMessage = UIMessage<AgentMetadata, AgentDataParts>;
import type {Project} from '../sandbox/project';
import type {Checkpoint, TurnDiff} from './types';

const COMMIT = /^[0-9a-f]{7,40}$/;

async function git(project: Project, args: string[]) {
  const {exitCode, output} = await project.run('git', args);
  if (exitCode !== 0) throw new Error(`git ${args[0]} failed (exit ${exitCode})`);
  return output.trim();
}

const head = (project: Project) => git(project, ['rev-parse', 'HEAD']);

export async function commitTurn(project: Project, turnId: string, base?: string): Promise<{checkpoint: Checkpoint; diff: TurnDiff}> {
  await git(project, ['add', '-A']);
  const parentId = await head(project);
  const from = base ?? parentId;
  const diff = await git(project, ['diff', '--cached', from]);
  const filesTouched = (await git(project, ['diff', '--cached', '--name-only', from])).split('\n').filter(Boolean);
  await git(project, ['commit', '-q', '--allow-empty', '-m', `turn ${turnId}`]);
  return {
    checkpoint: {id: await head(project), parentId: from, sandboxId: project.id, turnId, createdAt: new Date().toISOString()},
    diff: {diff, filesTouched},
  };
}

export async function restoreCheckpoint(project: Project, checkpointId: string): Promise<string> {
  if (!COMMIT.test(checkpointId)) throw new Error('Not a checkpoint id.');
  await git(project, ['read-tree', '-u', '--reset', checkpointId]);
  await git(project, ['commit', '-q', '--allow-empty', '-m', `restore ${checkpointId}`]);
  return head(project);
}
import type {Project} from '../sandbox/project';
import {CHECKER_SCRIPT} from '../sandbox/runtime-check';
import {PREVIEW_PORT} from '../sandbox/starter';
import type {VerifyCheck, VerifyResult} from './types';

const MAX_ERROR_LINES = 40;
const tail = (output: string) => output.trim().split('\n').slice(-MAX_ERROR_LINES).join('\n');

async function timed(name: VerifyCheck['name'], fn: () => Promise<Omit<VerifyCheck, 'name' | 'durationMs'>>): Promise<VerifyCheck> {
  const start = Date.now();
  return {name, ...(await fn()), durationMs: Date.now() - start};
}

const script = (project: Project, name: 'typecheck' | 'build') =>
  timed(name, async () => {
    const {exitCode, output} = await project.run('npm', ['run', '--silent', name]);
    return exitCode === 0 ? {status: 'passed', errors: []} : {status: 'failed', errors: [tail(output)]};
  });

export function runtimeErrors(exitCode: number, output: string): Omit<VerifyCheck, 'name' | 'durationMs'> {
  const json = output.trim().split('\n').at(-1) ?? '';
  if (exitCode !== 0 || !json.startsWith('[')) return {status: 'skipped', errors: [`The runtime check could not run: ${tail(output)}`]};
  const errors: string[] = JSON.parse(json);
  return errors.length ? {status: 'failed', errors} : {status: 'passed', errors: []};
}

export async function verifyProject(project: Project): Promise<VerifyResult> {
  const typecheck = await script(project, 'typecheck');
  const build = await script(project, 'build');
  const runtime =
    build.status === 'failed'
      ? {name: 'runtime' as const, status: 'skipped' as const, errors: [], durationMs: 0}
      : await timed('runtime', async () => {
          const {exitCode, output} = await project.run('node', [CHECKER_SCRIPT, `http://localhost:${PREVIEW_PORT}`]);
          return runtimeErrors(exitCode, output);
        });
  const checks = [typecheck, build, runtime];
  return {ok: checks.every(c => c.status !== 'failed'), checks};
}
import {createAnthropic} from '@ai-sdk/anthropic';
import {createOpenAI} from '@ai-sdk/openai';
import {providerOf} from './models';
import type {ProviderCredential} from './types';

export function languageModel(modelId: string, credential: ProviderCredential) {
  if (providerOf(modelId) !== credential.provider) {
    throw new Error(`Model ${modelId} is not available for provider ${credential.provider}.`);
  }
  if (credential.provider === 'anthropic') {
    if (credential.kind !== 'api-key') throw new Error('Anthropic accepts API keys only.');
    return createAnthropic({apiKey: credential.apiKey})(modelId);
  }
  const token = credential.kind === 'api-key' ? credential.apiKey : credential.accessToken;
  return createOpenAI({apiKey: token})(modelId);
}

// Body credentials are API keys only; an OAuth token must come from the server-side session cookie.
export function parseCredential(value: unknown): ProviderCredential | null {
  if (typeof value !== 'object' || value === null) return null;
  const c = value as Record<string, unknown>;
  if ((c.provider !== 'openai' && c.provider !== 'anthropic') || c.kind !== 'api-key' || typeof c.apiKey !== 'string' || !c.apiKey) return null;
  return {provider: c.provider, kind: c.kind, apiKey: c.apiKey};
}
import {randomBytes} from 'node:crypto';
import {context, trace, TraceFlags} from '@opentelemetry/api';
import {TRACER_NAME} from './trace';
import type {TurnEvent} from './types';

export function logEvent(event: TurnEvent) {
  console.info('[event]', JSON.stringify(event));
  const parent = event.traceId
    ? trace.setSpanContext(context.active(), {traceId: event.traceId, spanId: randomBytes(8).toString('hex'), traceFlags: TraceFlags.SAMPLED, isRemote: true})
    : context.active();
  const span = trace.getTracer(TRACER_NAME).startSpan(`betterlook.event.${event.type}`, {}, parent);
  span.setAttributes({
    'langfuse.observation.type': 'event',
    'langfuse.observation.metadata.event': JSON.stringify(event),
    'langfuse.trace.metadata.lastEvent': event.type,
  });
  span.end();
}

export function parseKeepEvent(value: unknown): TurnEvent | null {
  const e = value as Record<string, unknown> | null;
  if (e?.type !== 'keep' || typeof e.turnId !== 'string') return null;
  return {type: 'keep', turnId: e.turnId, traceId: typeof e.traceId === 'string' ? e.traceId : undefined, at: new Date().toISOString()};
}
import {APICallError} from 'ai';
import type {ProviderId} from './types';

export const KEY_REJECTED = 'Your API key or sign-in was rejected. Check it and try again.';
export const RATE_LIMITED = 'The model provider is rate limiting requests. Wait a minute and try again.';
export const PROVIDER_FAILED = 'The model provider returned an error. Try again.';
export const VERIFY_FAILED = 'The change still fails its checks after one repair attempt. Restore the previous version or describe what to fix.';
export const UNVERIFIED = 'The change builds, but the visual check could not run, so it is not verified. Check the preview yourself.';
export const STEP_LIMIT = 'The agent hit its step limit before finishing. Send another message to let it continue.';
export const REFUSED = 'The model declined this request. Rephrase it or pick another model.';
export const SANDBOX_FAILED = 'The preview sandbox stopped responding. Reload to try again.';
export const SANDBOX_QUOTA = 'The preview sandbox has used its free monthly quota, so new sandboxes are paused until it resets.';

const PROVIDER_NAMES: Record<ProviderId, string> = {openai: 'OpenAI', anthropic: 'Anthropic'};

export const missingKey = ({provider, label}: {provider: ProviderId; label: string}) =>
  `${provider === 'openai' ? 'Sign in or add' : 'Add'} an ${PROVIDER_NAMES[provider]} API key to use ${label}.`;

// The SDK wraps errors it retried; the provider's status is on the last attempt.
const apiError = (error: unknown) => {
  const last = (error as {lastError?: unknown} | null)?.lastError ?? error;
  return APICallError.isInstance(last) ? last : null;
};

// Never forward provider text: OpenAI's 401 body echoes part of the key. Anthropic 529 overloaded and 5xx fall through to PROVIDER_FAILED.
export function userMessage(error: unknown): string {
  const status = apiError(error)?.statusCode;
  if (status === 401 || status === 403) return KEY_REJECTED;
  if (status === 429) return RATE_LIMITED;
  return PROVIDER_FAILED;
}

export function errorStatus(error: unknown): number | string {
  const api = apiError(error);
  return api ? (api.statusCode ?? 'no-status') : error instanceof Error ? error.name : 'unknown';
}

// Vercel Sandbox answers 402 payment_required once the Hobby quota is used up and creation pauses.
export const sandboxQuotaExceeded = (error: unknown) => (error as {response?: {status?: number}} | null)?.response?.status === 402;

export const sandboxMessage = (error: unknown) => (sandboxQuotaExceeded(error) ? SANDBOX_QUOTA : SANDBOX_FAILED);

